/**
 * The script checks the files and directories structure, which are
 * generated by `npm pack` command.
 */
const tar = require('tar')
const util = require('util')
const fs = require('fs')
const { rimraf } = require('rimraf')

const stat = util.promisify(fs.stat);

/**
 * Default directory name where the package is unziped.
 *
 * @type {string}
 */
const UNPACKED_DIR_NAME = 'package'
/**
 * The list of file we check if they exists in the package.
 *
 * @type {string[]}
 */
const FILES_CHECKLIST = [
  'LICENSE.txt',
  'CHANGELOG.md',
  'README.md',
  'package.json',
  'script/postinstall-skills-message.js',
  'commonjs/index.js',
  'commonjs/HyperFormula.js',
  'dist/hyperformula.js',
  'es/index.mjs',
  'es/HyperFormula.mjs',
  'typings/index.d.ts',
  'typings/HyperFormula.d.ts',
  'dist/languages/plPL.js',
  'es/i18n/languages/plPL.mjs',
  'commonjs/i18n/languages/plPL.js',
]

let received = false

process.stdin.resume()
process.stdin.on('data', function(data) {
  received = true

  if (!data) {
    throw Error('Missing STDIN stream');
  }

  const packageName = data.toString().replace(/\n/g, '');
  let errorCode = 0;

  tar.x({ file: packageName }).then(() => {
    return checkDirectoryTreeStructure()

  }).then(() => {
    console.log(`Publish package check: \u001b[0;32mOK\u001b[0m`)

  }).catch((err) => {
    errorCode = 1;
    console.log(`Publish package check: \u001b[0;31mERROR\u001b[0m (${err.message})`)

  }).finally(() => {
    return Promise.all([
      removePackage(packageName),
      removePackage(UNPACKED_DIR_NAME),
    ])

  }).catch((err) => {
    errorCode = 1;
    console.log(`Publish package check: Error while cleanup the stuff (${err.message})`)

  }).finally(() => {
    process.exit(errorCode)
  })
})
// A failed `npm pack` prints no package name (`--silent` also hides its error),
// and the pipe ignores its exit code, so empty input must fail the check.
process.stdin.on('end', function() {
  if (!received) {
    console.log(`Publish package check: \u001b[0;31mERROR\u001b[0m (no package name on STDIN - npm pack failed)`)
    process.exit(1)
  }
})
process.stdout.on('error', (err) => {
  if (err.code === 'EPIPE') {
    return process.exit()
  }

  process.emit('error', err)
})

async function checkDirectoryTreeStructure() {
  for (let i = 0; i < FILES_CHECKLIST.length; i++) {
    const stats = await stat(`${UNPACKED_DIR_NAME}/${FILES_CHECKLIST[i]}`)

    if (!stats || !stats.isFile()) {
      throw new Error(`No such file (${FILES_CHECKLIST[i]}) in the checklist or it is not described as a regular file`);
    }
  }
}

async function removePackage(files) {
  return rimraf(files)
}
